@startuml

class Project {
  +StartDate
  +EndDate
}

class WorkProduct {
  +Description
  +PercentComplete
  +Validate()
}

class Requirement extends WorkProduct {
  +Media
  +Validate()
  +Publish()
}

class System extends WorkProduct {
  +Platform
  +Validate()
  +Deploy()
}

class Manager {
  +InitiateProject()
  +TerminateProject()
}

class Team {
}

Manager "1" -- "*" Project : Manage
Manager "1" -- "*" Team : Leads
Team "1" -- "1" Project : Executes
Project "1" *-- "1..*" Requirement : Input
Project "1" -- "1" System : Output

@enduml

